import { icon, timeline } from './ui.js';
import { RULESET } from './data.js';
const number=n=>new Intl.NumberFormat('de-DE').format(n);
export const gradeDescriptions=['Geringe Beeinträchtigungen der Selbstständigkeit.','Erhebliche Beeinträchtigungen der Selbstständigkeit.','Schwere Beeinträchtigungen der Selbstständigkeit.','Schwerste Beeinträchtigungen der Selbstständigkeit.','Schwerste Beeinträchtigungen mit besonderen Anforderungen an die pflegerische Versorgung.'];
export function gradeDisplay(grade){
  const min=RULESET.gradeThresholds[grade],max=grade===5?100:RULESET.gradeThresholds[grade+1];
  return `<span class="grade-display-number" aria-hidden="true">${grade}</span><div><h3>Pflegegrad ${grade}</h3><p class="grade-threshold">${number(min)} ${grade===5?'bis':'bis unter'} ${number(max)} Punkte</p><p class="grade-description">${gradeDescriptions[grade-1]}</p></div>`;
}
